			/**
			 * 공통코드 존재시 공통 데이터 셋 생성
			 * @param {String} psData
			 */
			function createCmnDataSet(psData) {
			    
			    var voDsBoardColList = app.lookup("dsBoardColList");
			    var voData = JSON.parse(psData);
			    var vaCmnDsNm = [];
			    
			    for (var i = 0; i < voDsBoardColList.getRowCount(); i++) {
			        var vsCmnCd = voDsBoardColList.getValue(i, "CMMNS_CD_ID");
			        
			        if (!ValueUtil.isNull(vsCmnCd)) {
			            var vsDsNm = "ds" + voDsBoardColList.getValue(i, "NTABRD_COL_ESNTAL_ID") + vsCmnCd;
			            var dataSet = new cpr.data.DataSet(vsDsNm);
			            dataSet.parseData({
			                "columns": [{
			                        "name": "CMMNS_CD_VALUE"
			                    },
			                    {
			                        "name": "CMMNS_CD_VALUE_NM"
			                    }
			                ]
			            });
			            app.register(dataSet);
			            
			            dataSet.build(voData[vsDsNm]);
			            vaCmnDsNm.push(vsDsNm);
			        }
			    }
			    
			    return vaCmnDsNm;
			}

