			/*
			 * 루트 컨테이너에서 init 이벤트 발생 시 호출.
			 * 앱이 최초 구성될 때 발생하는 이벤트 입니다.
			 */
			function onBodyInit(e) {
			    
			    // 로그인 사용자 정보
			    /** @type cpr.data.DataMap */
			    var voUserAuth = util.Auth.getUserInfo(app);
			    
			    if (voUserAuth) {
			        var voUserInfo = voUserAuth.getDatas();
			        app.lookup("dmUserInfo").build(voUserInfo);
			        
			        // TODO 관리자 권한(임시 테스트를 위해 역할 구분 코드 활용, 1: 총괄관리자, 2 : 관리자, 3 : 사용자)
			        var vsGroupAuthrtSeCd = voUserInfo["GROUP_AUTHRT_SE_CD"].substr(1, 2);
			        
			        // 선택삭제 권한 부여(동일한 조건이지만 추 후 필요를 고려해 구분)
			        if (vsGroupAuthrtSeCd == "00" || vsGroupAuthrtSeCd == "10" || vsGroupAuthrtSeCd == "20") { // 총괄 관리자
			            app.lookup("grdBoardList").columnVisible(0, true);
			            app.lookup("comBtnGrid").visibleDeleteButton = true;
			            mbAdmin = true;
			        }
			        
			        // 로그인 안 한 경우
			    } else {
			        var comBtnGrid = app.lookup("comBtnGrid");
			        comBtnGrid.visible = false;
			    }
			}

			/*
			 * 루트 컨테이너에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad( /* cpr.events.CEvent */ e) {
			    
			    // 자바 컨트롤러에서 파라미터 받아옴.
			    var strBoardId = cpr.core.Platform.INSTANCE.getParameter("strBoardId");
			    
			    if (strBoardId) {
			        msBrdId = strBoardId;
			        util.DataMap.setValue(app, "dmInit", "strBoardId", msBrdId);
			        
			        var appheader = app.lookup("appheader");
			        appheader.setAppProperty("title", "로그인 공지사항");
			        appheader.setAppProperty("useBtnBookMark", false);
			        appheader.setAppTitle();
			        
			        doInit();
			    }
			    
			    /*공통 서비스 호출 (공통코드, 현재일자)*/
			    util.Submit.send(app, "subOnLoad", function(pbSuccess) {
			        if (pbSuccess) {
			            util.ComUdcBtn.dispatchEvent(app, "btnSearch", "click");
			        }
			    });
			}

			/*
			 * 사용자 정의 컨트롤에서 search 이벤트 발생 시 호출.
			 * 조회버튼 클릭시 이벤트
			 */
			function onBtnSearchSearch( /* cpr.events.CUIEvent */ e) {
			    
			    // 조회 버튼을 클릭한 재조회시 페이지 번호 초기화
			    app.lookup("dmPageInfo").setValue("pageNo", 1);
			    
			    doList();
			}

			/*
			 * 그리드에서 cell-click 이벤트 발생 시 호출.
			 * Grid의 Cell 클릭시 발생하는 이벤트.
			 */
			function onGrdListCellClick2( /* cpr.events.CGridMouseEvent */ e) {
			    
			    // 체크박스 컬럼 선택시 예외처리
			    if (e.cellIndex == 0) return false;
			    
			    var vsRlsYn = util.DataSet.getValue(app, "dsBoardList", e.rowIndex, "RLS_YN");
			    
			    if (vsRlsYn == "N") { // 비공개시 본인 및 관리자만 조회가능
			        
			        var vsFrstRgtrId = util.DataSet.getValue(app, "dsBoardList", e.rowIndex, "FRST_RGTR_ID");
			        
			        // 본인 게시글 이거나 관리자일 경우 조회       
			        if (vsFrstRgtrId == util.DataMap.getValue(app, "dmUserInfo", "USER_ID") || mbAdmin) {
			            setDtlData("READ");
			        } else {
			            util.Msg.alert(app, "비공개 게시글 입니다.");
			        }
			        
			    } else {
			        setDtlData("READ");
			    }
			}

