			/*
			 * 버튼(btnExpand)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnExpandClick( /* cpr.events.CMouseEvent */ e) {
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btnExpand = e.control;
			    
			    // 조회 조건 그룹 보임 처리      
			    var vcGrpSearchCont = app.lookup("grpSearch");
			    var vcGrpData = app.lookup("grpData");
			    var vcBtnExpand = app.lookup("btnExpand");
			    
			    if (vcGrpSearchCont.getLayout().isRowVisible(1)) {
			        vcGrpSearchCont.getLayout().setRowVisible(1, false);
			        vcBtnExpand.style.setClasses("btn-header-plus");
			        
			    } else {
			        vcGrpSearchCont.getLayout().setRowVisible(1, true);
			        vcBtnExpand.style.setClasses("btn-header-minus");
			    }
			    
			    cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function() {
			        var vnHeight = vcGrpSearchCont.getActualRect().height;
			        var voConst = {
			            height: "calc(100% - " + (vnHeight + 90) + "px)"
			        }
			        vcGrpSearchCont.getParent().updateConstraint(vcGrpData, voConst);
			    });
			    
			}

			/*
			 * 루트 컨테이너에서 property-change 이벤트 발생 시 호출.
			 * 앱의 속성이 변경될 때 발생하는 이벤트 입니다.
			 */
			function onBodyPropertyChange(e) {
			    
			    console.log("이게설마?", e.property);
			    // 화면이 오픈될때 메인화면에서 PROGRAM_RM_CN값을 전달함
			    if (e.property == "PROGRAM_RM_CN") {
			        var vnStrIdx = e.newValue.indexOf("BOARD_ID_");
			        if (vnStrIdx == 0) {
			            msBrdId = e.newValue.substr(9, e.newValue.length);
			            util.DataMap.setValue(app, "dmInit", "strBoardId", msBrdId);
			            
			            doInit();
			        }
			    }
			}

